<?php declare(strict_types=1); require_once __DIR__.'/config.php';require_once __DIR__.'/lib/common.php';[$from,$to]=tp_window();$rows=tp_db()->query("SELECT * FROM tp_vessels WHERE tesla_flag=1 ORDER BY COALESCE(eta,first_seen_at) DESC LIMIT 50")->fetchAll(); ?>
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tesla 입항현황</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f5f7}.hero{background:#111;color:#fff;border-radius:24px}.card{border:0;border-radius:18px}</style></head><body><div class="container py-4" style="max-width:900px"><div class="hero p-4 mb-4"><h1 class="fw-bold">TESLA PORT</h1><div class="opacity-75">테슬라 국내 입항 · 통관 모니터</div><div class="small opacity-50 mt-2">자동조회 범위 <?=h($from)?> ~ <?=h($to)?></div></div><?php if(!$rows):?><div class="alert alert-secondary">아직 확인된 Tesla 입항정보가 없습니다.</div><?php endif?><?php foreach($rows as $r):?><div class="card shadow-sm mb-3"><div class="card-body"><div class="d-flex justify-content-between"><b><?=h($r['model_guess']?:'Tesla 차량')?></b><span><?=h($r['eta'])?></span></div><h4 class="mt-2"><?=h($r['vessel_name'])?></h4><div><?=h($r['origin_port'])?> → <?=h($r['port_name'])?></div><div class="mt-2"><span class="badge text-bg-dark"><?=h($r['vehicle_count'])?>대</span> <span class="badge text-bg-light"><?=h($r['cargo_status']?:'확인중')?></span></div></div></div><?php endforeach?><p class="small text-secondary">모델 정보는 공개 화물정보·중량 등을 이용한 추정값이 포함될 수 있습니다.</p></div></body></html>
